# Base64 데이터를 원래의 바이너리 데이터로 디코딩
wav_data = base64.b64decode(b64_data)

# 파일 저장 경로 설정
output_dir = os.path.join("resources", "ester_egg")
output_path = os.path.join(output_dir, "silent_prime.wav")

try:
    # 폴더가 없으면 생성
    os.makedirs(output_dir, exist_ok=True)

    # 파일 쓰기
    with open(output_path, 'wb') as f:
        f.write(wav_data)
    
    print(f"성공: 무음 파일이 다음 경로에 생성되었습니다.\n-> {os.path.abspath(output_path)}")

except Exception as e:
    print(f"오류: 파일 생성에 실패했습니다.\n-> {e}")
    
    